#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *a = (long long *)malloc(sizeof(long long) * n);
    if (a == NULL) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    int i = 0, j = n - 1;
    long long ops = 0;

    while (i < j) {
        if (a[i] == a[j]) {
            i++;
            j--;
        } else if (a[i] < a[j]) {
            a[i + 1] += a[i];
            i++;
            ops++;
        } else {
            a[j - 1] += a[j];
            j--;
            ops++;
        }
    }

    printf("%lld\n", ops);
    free(a);
    return 0;
}
