#include <stdlib.h>

static char buf[1 << 20];
static int buf_idx = 0, buf_len = 0;

static inline int read_char() {
    if (buf_idx >= buf_len) {
        buf_len = fread(buf, 1, sizeof(buf), stdin);
        buf_idx = 0;
        if (buf_len == 0) return EOF;
    }
    return buf[buf_idx++];
}

static inline long long read_ll() {
    int c = read_char();
    while (c <= ' ' && c != EOF) c = read_char();
    long long x = 0;
    while (c > ' ') {
        x = x * 10 + (c - '0');
        c = read_char();
    }
    return x;
}

int main() {
    int n = (int)read_ll();
    long long *a = (long long*)malloc(n * sizeof(long long));
    for (int i = 0; i < n; ++i) {
        a[i] = read_ll();
    }

